def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rays = {}
    shifts = {1: (-1, 2), 2: (0, -4), 3: (3, 0), 6: (-6, 0)}
    # Extend each numbered marker by its fixed displacement, in an L/horizontal-then-vertical path.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in shifts:
                continue
            dr, dc = shifts[color]
            er, ec = r + dr, c + dc
            if not (0 <= er < h and 0 <= ec < w):
                continue
            path = []
            rr, cc = r, c
            while cc != ec:
                cc += 1 if ec > cc else -1
                if (rr, cc) != (er, ec):
                    path.append((rr, cc))
            while rr != er:
                rr += 1 if er > rr else -1
                if (rr, cc) != (er, ec):
                    path.append((rr, cc))
            # Place the copy and the color-5 trail without overwriting input markers.
            if grid[er][ec] == 0:
                out[er][ec] = color
            rays[color] = rays.get(color, []) + [set(path)]
            for pr, pc in path:
                if grid[pr][pc] == 0 and out[pr][pc] == 0:
                    out[pr][pc] = 5
    # Intersections of the vertical 3/6 and horizontal 2 rays become 4.
    crossings = set()
    for cr in (2, 3, 6):
        for hc in (2,):
            for vpath in rays.get(cr, []):
                for hpath in rays.get(hc, []):
                    crossings |= vpath & hpath
    # Also include intersections at a ray endpoint if that endpoint lies on the other ray.
    # A crossing is defined by overlap of the drawn trails; original endpoints remain colored.
    for r, c in crossings:
        out[r][c] = 4
    # Each crossing launches the diagonal color-4 trail down-left, four cells.
    for r, c in crossings:
        for k in range(1, 5):
            rr, cc = r + k, c - k
            if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 0:
                out[rr][cc] = 4
    return out
